sections.code:
* {
  background-color: #{{ colors.background.default.hex_stripped }} !important;
  color: #{{ colors.on_surface.default.hex_stripped }} !important;
  border-color: #{{ colors.outline_variant.default.hex_stripped }} !important;
}
a, a:visited {
  color: #{{ colors.primary.default.hex_stripped }} !important;
}
input, textarea, select {
  background-color: #{{ colors.surface_container.default.hex_stripped }} !important;
  color: #{{ colors.on_surface.default.hex_stripped }} ;
}
